(function(){
  const F={k:'#17152b',W:'#f4efe0',w:'#c9c4dc',y:'#ffe27a',Y:'#d89a1c',r:'#e8302d',R:'#8a1a1a',o:'#ff8a3d',g:'#5aa02c',G:'#2f6a1c',b:'#5aa0e8',B:'#2c4f8a',c:'#8fd0e8',n:'#8a5a2b',N:'#c98a4b',s:'#8b93ad',S:'#4a4566',v:'#8a5fa8',V:'#4a2a68',p:'#ff8aa8',P:'#b8334a',t:'#3fd0b0',T:'#2a9a82',u:'#2c2847',e:'#17152b'};
  for(const id of Object.keys(MON_ART)){
    const [m,a,rs]=MON_ART[id],rows=rs.split('|');
    const p={...F,m,M:shadeC(m,.68),l:lightC(m,.42),a,A:shadeC(a,.68),L:lightC(a,.45)};
    const g=rows.map(r=>r.split('').map(c=>c==='.'?null:(p[c]||null)));
    const o=g.map(r=>r.slice());
    for(let y=0;y<16;y++)for(let x=0;x<16;x++)if(!g[y][x])for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const c=(g[y+dy]||[])[x+dx];if(c&&c!=='#17152b'){o[y][x]='#17152b';break;}}
    const E=Array(16).fill(null);
    GEN[id]={frames:[o,[E,...o.slice(0,9),...o.slice(10)],o,[...o.slice(1,10),o[9],...o.slice(10)]]};
  }
})();
for(const id of Object.keys(GEN))if(!GEN[id].grid)FR[id]=4;
const spr=(id,cls='')=>{const n=id.replace(/^s-/,'');ensureSpr(n);const f=FR[n]||1;return `<i class="px${f>1?'':' s1'} ${cls}" style="--f:${f};--fd:${FD[n]||.22}s;background-image:var(--sp-${n})"></i>`;};
function mkFrames(name,A){
  if(['hero','slime','archer','brute','ghost','king'].includes(name)){
    const E='.'.repeat(16);
    return [A,[E,...A.slice(0,9),...A.slice(10)],A,[...A.slice(1,10),A[9],...A.slice(10)]];
  }
  if(name==='coin')return [1,.62,.3,.62].map(k=>A.map(r=>{let o='';for(let x=0;x<16;x++){const sx=Math.round(7.5+(x-7.5)/k);o+=(sx>=0&&sx<16)?r[sx]:'.';}return o;}));
  const rep=c=>A.map(r=>r.replace(/\*/g,c));
  if(name==='bomb')return [rep('z'),rep('o')];
  if(name==='stairs')return [rep('z'),rep('y'),rep('Y')];
  return [rep('z')];
}
const SPRDONE=new Set(),ZDONE=new Set(['gruft']);
function paintStrip(frames,colorOf,sz=16){
  const cv=document.createElement('canvas');cv.width=sz*frames.length;cv.height=sz;
  const cx=cv.getContext&&cv.getContext('2d');if(!cx)return null;
  frames.forEach((rows,f)=>rows.forEach((row,y)=>{for(let x=0;x<sz;x++){const c=colorOf(row[x]);if(c){cx.fillStyle=c;cx.fillRect(f*sz+x,y,1,1);}}}));
  const u=`url(${cv.toDataURL()})`;cv.width=cv.height=0;return u;
}
function ensureSpr(id){
  if(SPRDONE.has(id))return;SPRDONE.add(id);
  const def=GEN[id];if(!def)return;
  const E=Array(16).fill(null);
  const grid=def.frames?null:(def.grid||genGrid(def.body,def.main,def.acc,def.kind));
  const fr=def.frames?def.frames:def.grid?[grid]:[grid,[E,...grid.slice(0,9),...grid.slice(10)],grid,[...grid.slice(1,10),grid[9],...grid.slice(10)]];
  const u=paintStrip(fr,c=>c,def.size||16);
  if(u)document.documentElement.style.setProperty('--sp-'+id,u);
}
function ensureZone(kd){
  if(ZDONE.has(kd))return;ZDONE.add(kd);
  const pal={...PALJ,...ZPAL[kd]};
  for(const name of ZNAMES){
    const u=paintStrip(mkFrames(name,zdeco(name,ART[name],kd)),c=>pal[c]);
    if(u)ZURL[kd][name]=u;
  }
}
function initSprites(){
  const root=document.documentElement;
  for(const name of Object.keys(ART)){
    const u=paintStrip(mkFrames(name,ART[name]),c=>PALJ[c]);
    if(u)root.style.setProperty('--sp-'+name,u);
  }
  for(const name of ZNAMES){ZURL.gruft[name]=root.style.getPropertyValue('--sp-'+name);}
  const st=document.createElement('style');
  st.textContent=Object.keys(MT).map(id=>`.nf i.${id}{background:${MT[id].col}}`).join('\n');
  document.head.appendChild(st);
}
function fillStatic(){document.querySelectorAll('[data-spr]').forEach(e=>{e.innerHTML=spr(e.dataset.spr);});}

const fmt=n=>Number(n).toLocaleString(LANG==='en'?'en-US':'de-DE');

